/**
 * Types for the LinkedIn archive (/linkedin). The data itself is generated by
 * scripts/linkedin/build-linkedin-archive.mjs into linkedinArchiveData.ts.
 */

export type LiKind = "image" | "video" | "document";
export type LiContext = "post" | "article" | "comment" | "profile";

export interface LiItem {
  /** Stable 4-digit id from the LinkedIn rich-media export, oldest first. */
  idx: string;
  kind: LiKind;
  /** Upload day, YYYY-MM-DD. */
  date: string;
  /** LinkedIn's own label, e.g. "post photo", "article cover photo". */
  label: string;
  context: LiContext;
  format: string;
  topics: string[];
  entities: string[];
  /** One plain sentence describing what the media shows. */
  description: string;
  width: number;
  height: number;
  /** Seconds, videos only. */
  duration?: number;
  /** "pdf" or "pptx", documents only. */
  docExt?: string;
  /** Present only in local previews: the item is waiting for the owner's review and must never ship. */
  review?: boolean;
}

export type LiNodeType = "topic" | "entity" | "item";

export interface LiGraphNode {
  id: string;
  type: LiNodeType;
  /** Layout position in the graph's own coordinate box (see LiGraph width/height). */
  x: number;
  y: number;
  label: string;
  /** Items attached to a topic or entity node. */
  count?: number;
  /** Item nodes only. */
  idx?: string;
  kind?: LiKind;
}

export interface LiGraph {
  width: number;
  height: number;
  nodes: LiGraphNode[];
  /** [source id, target id]; every edge joins an item to a topic or an entity. */
  edges: [string, string][];
}
